/** Real plugin metadata and schedulers. Completed-site and offline Player/View are explicit fixtures. */
public final class EnvironmentDistrictsProbe extends AdmissionsProbe {
    NeverLandTownyEnvironment environmentPlugin;EnvironmentService environment;NeverLandTownyDistricts districtsPlugin;DistrictService districts;DataStore buildings;Path data;byte[] originalData,originalDistricts;
    void in(Work work){try{work.run();}catch(Throwable error){fail(error);}}
    @SuppressWarnings("unchecked")Map<String,Object> map(Object value){return(Map<String,Object>)value;}
    @SuppressWarnings("unchecked")Map<String,Map<String,Object>> rows(Map<String,Object> report){return(Map<String,Map<String,Object>>)report.get("rows");}
    void ready(int remaining,Consumer<Map<String,Object>> next)throws Exception{environment.refreshDistricts(T);var report=environment.districts(T);if(Boolean.TRUE.equals(report.get("available"))){next.accept(report);return;}if(!Boolean.TRUE.equals(report.get("pending"))||remaining<=0)throw new AssertionError("environment districts not ready: "+report);later(1,()->ready(remaining-1,next));}
    @Override void setup()throws Exception{
        environmentPlugin=(NeverLandTownyEnvironment)Bukkit.getPluginManager().getPlugin("NeverLandTownyEnvironment");environment=(EnvironmentService)field(environmentPlugin,"service");districtsPlugin=(NeverLandTownyDistricts)Bukkit.getPluginManager().getPlugin("NeverLandTownyDistricts");districts=(DistrictService)field(districtsPlugin,"service");buildings=(DataStore)field(Bukkit.getPluginManager().getPlugin("NeverLandTownyBuilds"),"dataStore");mayor=actor(M,"EnvironmentDistrictMayor");data=environmentPlugin.getDataFolder().toPath().resolve("environment-data.yml");
        check(environmentPlugin.isEnabled()&&environmentPlugin.getDescription().getVersion().equals("0.2.1"),"validated Environment 0.2.1 enabled on actual Folia with Towny Builds Districts");
        if(restart){town=TownyAPI.getInstance().getTown(T);environment.refreshView();ready(80,r->in(()->resume(r)));return;}
        var u=TownyUniverse.getInstance();u.newTownInternal("EnvDistrictCity",T);town=TownyAPI.getInstance().getTown(T);var resident=u.getDataSource().newResident("EnvironmentDistrictMayor",M);resident.setTown(town);town.setMayor(resident);resident.save();
        for(int x=-2;x<=15;x++)for(int z=-3;z<=3;z++){var claim=new TownBlock(x,z,u.getWorld(world.getName()));u.addTownBlock(claim);claim.setTown(town);if(x==0&&z==0)town.setHomeBlock(claim);claim.save();}town.setSpawn(origin);town.save();
        for(var e:Map.of("town_hall",0,"park",5,"forge",12).entrySet()){var site=new ConstructionSite(e.getKey(),world.getUID(),e.getValue()*16+8,160,8,BlockFace.NORTH,5,5,1,false);site.blueprintSet(BlueprintCatalog.currentPin(e.getKey(),BuildingStyle.MEDIEVAL));buildings.town(T).setConstructionSite(site);buildings.town(T).setLevel(e.getKey(),5);}buildings.markDirty();buildings.saveOrThrow();
        var green=new HashSet<Cell>();var industry=new HashSet<Cell>();for(int x=2;x<=8;x++)for(int z=-3;z<=3;z++)green.add(new Cell(world.getUID(),x,z));for(int x=9;x<=15;x++)for(int z=-3;z<=3;z++)industry.add(new Cell(world.getUID(),x,z));districts.put(new District(T,"green","Парковый квартал",DistrictType.RESIDENTIAL,green),true);districts.put(new District(T,"industry","Мастерские",DistrictType.INDUSTRIAL,industry),true);
        ((ru.neverland.townyenvironment.data.EnvironmentRepository)field(environment,"repository")).put(T,new ru.neverland.townyenvironment.model.EnvironmentState(55,7,false));
        environment.refreshView();check(environment.observation(T).ready()&&environment.observation(T).levels().get("park")==5&&environment.observation(T).levels().get("forge")==5,"actual existing ecological bridge sees two operational level-V footprints");
        originalData=Files.exists(data)?Files.readAllBytes(data):null;originalDistricts=Files.readAllBytes(districtsPlugin.getDataFolder().toPath().resolve("districts-data.yml"));ready(80,r->in(()->baseline(r)));
    }
    void totals(Map<String,Object> report)throws Exception{var totals=map(report.get("totals"));for(String key:List.of("emissions","cleaning","change")){var sum=BigDecimal.ZERO;for(var row:rows(report).values())sum=sum.add(new BigDecimal((String)row.get(key)));check(sum.compareTo(new BigDecimal((String)totals.get(key)))==0,"district rows preserve city "+key);}
        var pressure=environment.observation(T).pressure();check(new BigDecimal((String)totals.get("emissions")).compareTo(BigDecimal.valueOf(pressure.emissions()))==0&&new BigDecimal((String)totals.get("cleaning")).compareTo(BigDecimal.valueOf(pressure.cleaning()))==0,"decomposition exactly matches old engine pressure without changed rates");
        for(var row:rows(report).values())for(String key:List.of("emissions","cleaning")){var sum=BigDecimal.ZERO;for(var source:map(row.get("sources")).values())sum=sum.add(new BigDecimal((String)map(source).get(key)));check(sum.compareTo(new BigDecimal((String)row.get(key)))==0,"each district preserves its complete source "+key);}
    }
    void baseline(Map<String,Object> report)throws Exception{totals(report);check(rows(report).size()==3&&map(rows(report).get("district:green").get("sources")).containsKey("park")&&map(rows(report).get("district:industry").get("sources")).containsKey("forge"),"physical park and forge assignments match genuine registered footprints");check(rows(report).get("district:green").get("greenBuildings").equals(1)&&rows(report).get("city").get("greenBuildings").equals(0)&&map(rows(report).get("city").get("sources")).containsKey("@nature"),"natural recovery remains separate from constructed green buildings");
        var future=java.util.concurrent.CompletableFuture.supplyAsync(()->environment.districts(T));later(2,()->{check(future.isDone()&&Boolean.TRUE.equals(future.join().get("available")),"async district API returns ready immutable report without waiting for SuiteState");menu(report);});
    }
    void menu(Map<String,Object> report)throws Exception{environmentPlugin.getCommand("townyenvironment").execute(mayor,"environment",new String[]{});check(windows.get(M).getItem(47).getType()==Material.FILLED_MAP,"native main ecology menu has district button");environmentPlugin.getCommand("townyenvironment").execute(mayor,"environment",new String[]{"districts"});String text=lore(mayor,4);check(text.contains("МСК")&&text.contains("Отдельных штрафов"),"native district header explains city-wide effects with Moscow timestamp");
        var click=new InventoryClickEvent(view(mayor,M),InventoryType.SlotType.CONTAINER,11,ClickType.LEFT,InventoryAction.PICKUP_ALL);Bukkit.getPluginManager().callEvent(click);check(click.isCancelled(),"native district drilldown prevents taking menu icon");later(2,()->{check(windows.get(M).getItem(4).getItemMeta().getDisplayName().contains("Парковый квартал")&&windows.get(M).getItem(10).getType()==Material.OAK_SAPLING,"district click opens complete native green source list");var denied=limitedActor(M,"EnvironmentDistrictMayor",true);var before=windows.get(M);environmentPlugin.getCommand("townyenvironment").execute(denied,"environment",new String[]{"districts"});check(windows.get(M)==before,"revoked use permission prevents opening district board");var visitor=limitedActor(P,"EnvironmentVisitor",false);environmentPlugin.getCommand("townyenvironment").execute(visitor,"environment",new String[]{"districts"});check(!windows.containsKey(P),"resident without town cannot inspect district board");toggles(report);});
    }
    boolean sameFile()throws Exception{return originalData==null?!Files.exists(data):Arrays.equals(originalData,Files.readAllBytes(data));}
    void toggles(Map<String,Object> report)throws Exception{var state=environment.state(T);var pressure=environment.observation(T).pressure();double happiness=environment.happiness(T),food=environment.agricultureMultiplier(T,"agrarian_complex");check(sameFile()&&Arrays.equals(originalDistricts,Files.readAllBytes(districtsPlugin.getDataFolder().toPath().resolve("districts-data.yml"))),"API and native viewing leave original ecological and district files unchanged");
        for(Object setting:List.of(false,"broken")){environmentPlugin.getConfig().set("districts.enabled",setting);environment.refreshDistricts(T);check(Boolean.FALSE.equals(environment.districts(T).get("available"))&&environment.state(T).equals(state)&&environment.observation(T).pressure().equals(pressure)&&environment.happiness(T)==happiness&&environment.agricultureMultiplier(T,"agrarian_complex")==food,"disabled or malformed optional setting never changes simulation pressure effects or stored state");}environmentPlugin.getConfig().set("districts.enabled",true);districtsPlugin.getConfig().set("assessment.enabled",false);environment.refreshDistricts(T);check(Boolean.FALSE.equals(environment.districts(T).get("available"))&&environment.state(T).equals(state)&&environment.happiness(T)==happiness&&environment.agricultureMultiplier(T,"agrarian_complex")==food,"unavailable optional district assessment pauses only district explanation");districtsPlugin.getConfig().set("assessment.enabled",true);ready(80,r->in(()->{check(map(report.get("totals")).equals(map(r.get("totals"))),"source recovery reconstructs exact unchanged city pressure");Files.writeString(proof.resolve("expected.txt"),new TreeMap<>(map(r.get("totals"))).toString()+"\n"+environment.state(T).toString());finishEnvironment();}));}
    void resume(Map<String,Object> report)throws Exception{check(town!=null&&districts.list(T).size()==2&&buildings.town(T).level("park")==5,"actual district and green building fixtures survive full restart");totals(report);var expected=Files.readAllLines(proof.resolve("expected.txt"));check(new TreeMap<>(map(report.get("totals"))).toString().equals(expected.get(0))&&environment.state(T).toString().equals(expected.get(1)),"restart reconstructs exact district pressure and preserves pollution history");finishEnvironment();}
    Player limitedActor(UUID id,String name,boolean denyUse){var base=actor(id,name);var handler=java.lang.reflect.Proxy.getInvocationHandler(base);return(Player)java.lang.reflect.Proxy.newProxyInstance(Player.class.getClassLoader(),new Class<?>[]{Player.class},(proxy,method,args)->{if(method.getName().equals("hasPermission")&&denyUse&&args[0].equals("neverlandtownyenvironment.use"))return false;return handler.invoke(base,method,args);});}
    void finishEnvironment()throws Exception{TownyUniverse.getInstance().getDataSource().saveAll();Files.writeString(proof.resolve((restart?"restart":"first")+"-passed.txt"),"PASS "+checks+" assertions; real Folia Towny Builds Districts Environment, precise pressure decomposition, physical green source assignments, cached API, native source menu, permissions, neutral settings/supplier failure and full restart; explicit persisted completed-site fixtures and offline Player InventoryView EntityScheduler; no tree scanning, client or bank transaction claimed\n");Bukkit.getGlobalRegionScheduler().run(this,t->Bukkit.shutdown());}
}
